'use client';

// Bottom sheets (check-in, Unstick, Day Mode, Bridge). Generated by the
// shadcn/ui CLI on Radix Dialog, which traps focus inside and returns it to
// the button that opened the sheet; adapted to Tide's phone column, a close
// button labeled in words, and (v2) a drag handle: pull it down to dismiss.
// Dragging is only a shortcut; Close and Escape always work too.
import * as React from 'react';
import { cn } from '@/lib/utils';
import { Dialog as SheetPrimitive } from 'radix-ui';
import { XIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { copy } from '@/copy/en';

function Sheet({ ...props }: React.ComponentProps<typeof SheetPrimitive.Root>) {
  return <SheetPrimitive.Root data-slot="sheet" {...props} />;
}

function SheetTrigger({ ...props }: React.ComponentProps<typeof SheetPrimitive.Trigger>) {
  return <SheetPrimitive.Trigger data-slot="sheet-trigger" {...props} />;
}

function SheetClose({ ...props }: React.ComponentProps<typeof SheetPrimitive.Close>) {
  return <SheetPrimitive.Close data-slot="sheet-close" {...props} />;
}

function SheetPortal({ ...props }: React.ComponentProps<typeof SheetPrimitive.Portal>) {
  return <SheetPrimitive.Portal data-slot="sheet-portal" {...props} />;
}

function SheetOverlay({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Overlay>) {
  return (
    <SheetPrimitive.Overlay
      data-slot="sheet-overlay"
      className={cn(
        'fixed inset-0 z-50 bg-scrim duration-200 data-open:animate-in data-open:fade-in-0 data-closed:animate-out data-closed:fade-out-0',
        className,
      )}
      {...props}
    />
  );
}

// Pulling the handle down moves the sheet with the finger; letting go far
// enough (or with a quick flick) closes it, otherwise it springs back.
function useDragToDismiss(close: () => void) {
  const start = React.useRef<{ y: number; t: number } | null>(null);
  const [dy, setDy] = React.useState(0);
  const onPointerDown = (e: React.PointerEvent) => {
    start.current = { y: e.clientY, t: e.timeStamp };
    e.currentTarget.setPointerCapture(e.pointerId);
  };
  const onPointerMove = (e: React.PointerEvent) => {
    if (start.current) setDy(Math.max(0, e.clientY - start.current.y));
  };
  const onPointerUp = (e: React.PointerEvent) => {
    if (!start.current) return;
    const distance = Math.max(0, e.clientY - start.current.y);
    const velocity = distance / Math.max(1, e.timeStamp - start.current.t);
    start.current = null;
    setDy(0);
    if (distance > 120 || velocity > 0.6) close();
  };
  return { dy, handlers: { onPointerDown, onPointerMove, onPointerUp, onPointerCancel: onPointerUp } };
}

// Always slides up from the bottom inside the phone column; Tide has no side
// drawers.
function SheetContent({
  className,
  children,
  showCloseButton = true,
  closeLabel = copy.global.close,
  style,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Content> & {
  showCloseButton?: boolean;
  closeLabel?: string;
}) {
  const closeRef = React.useRef<HTMLButtonElement>(null);
  const { dy, handlers } = useDragToDismiss(() => closeRef.current?.click());
  return (
    <SheetPortal>
      <SheetOverlay />
      <SheetPrimitive.Content
        data-slot="sheet-content"
        className={cn(
          'fixed inset-x-0 bottom-0 z-50 mx-auto flex max-h-[94dvh] w-full max-w-[430px] flex-col rounded-t-[var(--radius-xl)] border-2 border-b-0 border-line bg-surface text-body text-ink shadow-sheet outline-none data-open:animate-in data-open:slide-in-from-bottom-full data-open:duration-(--dur-spring-gentle) data-open:ease-(--spring-gentle) data-closed:animate-out data-closed:slide-out-to-bottom-full data-closed:duration-(--dur-base) data-closed:ease-in',
          className,
        )}
        style={dy ? { ...style, transform: `translateY(${dy}px)` } : style}
        {...props}
      >
        <div
          aria-hidden
          className="absolute top-0 left-1/2 z-20 flex h-6 w-16 -translate-x-1/2 cursor-grab touch-none items-center justify-center active:cursor-grabbing"
          {...handlers}
        >
          <span className="h-1.5 w-10 rounded-full bg-line" />
        </div>
        {children}
        {showCloseButton ? (
          <SheetPrimitive.Close data-slot="sheet-close" asChild>
            <Button ref={closeRef} variant="quiet" size="sm" className="absolute top-3 right-3 z-10 bg-surface">
              <XIcon aria-hidden />
              {closeLabel}
            </Button>
          </SheetPrimitive.Close>
        ) : (
          <SheetPrimitive.Close ref={closeRef} tabIndex={-1} aria-hidden className="sr-only" />
        )}
      </SheetPrimitive.Content>
    </SheetPortal>
  );
}

function SheetHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return <div data-slot="sheet-header" className={cn('flex flex-col gap-1 px-5 pt-5 pr-28', className)} {...props} />;
}

function SheetFooter({ className, ...props }: React.ComponentProps<'div'>) {
  return <div data-slot="sheet-footer" className={cn('mt-auto flex flex-col gap-2 p-5', className)} {...props} />;
}

function SheetTitle({ className, ...props }: React.ComponentProps<typeof SheetPrimitive.Title>) {
  return (
    <SheetPrimitive.Title data-slot="sheet-title" className={cn('text-h2 font-bold text-ink', className)} {...props} />
  );
}

function SheetDescription({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Description>) {
  return (
    <SheetPrimitive.Description
      data-slot="sheet-description"
      className={cn('text-body text-ink-soft', className)}
      {...props}
    />
  );
}

export {
  Sheet,
  SheetTrigger,
  SheetClose,
  SheetContent,
  SheetHeader,
  SheetFooter,
  SheetTitle,
  SheetDescription,
};
